svg.script:
(function () {
  var SVGNS = 'http://www.w3.org/2000/svg';
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var drawRb;
  // ---- Roblox-LearnNLP: walk the Atrium, pass each portal's quiz, unlock the next ----
  var rb = document.getElementById('rb');
  if (rb) {
    var rq = function (id) { return document.getElementById(id); };
    var RX = [52, 126, 200, 274, 348], SCORE = [5, 4, 5, 5, 4],
        RNAMES = ['NAIVE BAYES', 'HIDDEN MARKOV MODELS', 'RNNs & LSTMs', 'ATTENTION', 'TRANSFORMERS'];
    var rbParts = [0, 1, 2, 3, 4].map(function (i) {
      return { beam: rq('rbBeam' + i), glow: rq('rbGlow' + i), surf: rq('rbSurf' + i), frame: rq('rbFrame' + i),
               num: rq('rbNum' + i), lock: rq('rbLock' + i), chk: rq('rbChk' + i), seg: rq('rbSeg' + i) };
    });
    var rbAv = rq('rbAv'), rbBody = rq('rbBody'), rbL1 = rq('rbL1'), rbL2 = rq('rbL2'), rbQuiz = rq('rbQuiz'),
        rbQuizBox = rq('rbQuizBox'), rbDots = rq('rbDots').getElementsByTagName('circle'), rbRes = rq('rbRes'),
        rbCount = rq('rbCount'), rbCap = rq('rbCap'), rbFade = rq('rbFade');
    var RACC = ['#2DD4BF', '#A78BFA', '#FBBF24', '#F472B6', '#38BDF8'];
    // 12.5 s loop: one 1.9 s beat per portal (walk in, quiz, unlock the next), then graduation
    var R0 = 500, STEP = 1900, GRAD = R0 + 5 * STEP, RLOOP = 12500, DONE = 1550;
    var rc = function (x) { return Math.max(0, Math.min(1, x)); };
    var re = function (x) { x = rc(x); return x * x * (3 - 2 * x); };
    var rs = function (f, a, b) { return rc((f - a) / (b - a)); };
    var lastRbCap = '', lastRbCount = '';
    var drawRb = function (t) {
      var f = t % RLOOP, m = Math.max(0, Math.min(5, Math.floor((f - R0) / STEP))), loc = f - R0 - m * STEP;
      var grad = f >= GRAD, done = 0;

      for (var i = 0; i < 5; i++) {
        var p = rbParts[i], dt = R0 + i * STEP + DONE;
        var u = i === 0 ? 1 : re(rs(f, dt - STEP, dt - STEP + 300)), isDone = f >= dt;
        if (isDone) done++;
        var pulse = 0.5 + 0.5 * Math.sin(t * 0.004 + i), flash = 0;
        if (m === i && loc >= 800 && loc < 1300) flash = 1 - Math.abs(loc - 950) / 350;
        var surf = grad ? 0.3 + 0.12 * pulse : isDone ? 0.22 : u * (0.14 + 0.12 * pulse);
        surf = Math.min(0.85, surf + 0.5 * rc(flash));
        p.surf.setAttribute('opacity', surf.toFixed(2));
        p.glow.setAttribute('opacity', Math.min(1, surf * 1.6).toFixed(2));
        p.beam.setAttribute('opacity', (grad ? 0.5 + 0.3 * pulse : isDone ? 0.12 : u * (0.25 + 0.25 * pulse)).toFixed(2));
        p.frame.setAttribute('opacity', u.toFixed(2));
        p.num.setAttribute('opacity', u.toFixed(2));
        p.lock.setAttribute('opacity', (1 - u).toFixed(2));
        var ck = re(rs(f, dt, dt + 220));
        p.chk.setAttribute('opacity', ck.toFixed(2));
        p.chk.setAttribute('transform', 'translate(' + (RX[i] + 15) + ' 111) scale(' + (0.4 + 0.6 * ck).toFixed(3) + ') translate(' + -(RX[i] + 15) + ' -111)');
        if (p.seg) p.seg.setAttribute('stroke-dashoffset', (74 * (1 - re(rs(f, dt, dt + 300)))).toFixed(1));
      }

      // the player walks to the open portal, steps in, and comes back out once the quiz is passed
      var ax = 14, ao = 1, as = 1, walking = false;
      if (f < R0) ax = 14;
      else if (m < 5) {
        var from = m === 0 ? 14 : RX[m - 1];
        if (loc < 800) { ax = from + (RX[m] - from) * re(loc / 800); walking = true; }
        else { ax = RX[m]; ao = loc < 1000 ? 1 - rs(loc, 800, 1000) : rs(loc, 1600, 1800); as = loc < 1000 ? 1 - 0.4 * rs(loc, 800, 1000) : 1; }
      } else ax = RX[4];
      var hop = walking ? -1.4 * Math.abs(Math.sin(loc * 0.022)) : grad ? -4 * Math.abs(Math.sin((f - GRAD) * 0.006)) : 0;
      rbAv.setAttribute('transform', 'translate(' + ax.toFixed(1) + ' 150) scale(' + as.toFixed(3) + ')');
      rbAv.setAttribute('opacity', ao.toFixed(2));
      rbBody.setAttribute('transform', 'translate(0 ' + hop.toFixed(2) + ')');
      var sw = walking ? 22 * Math.sin(loc * 0.022) : 0;
      rbL1.setAttribute('transform', 'rotate(' + sw.toFixed(1) + ' -1.7 -6.5)');
      rbL2.setAttribute('transform', 'rotate(' + (-sw).toFixed(1) + ' 1.7 -6.5)');

      // the quiz card: five answers come in one by one, then the pass mark
      if (m < 5 && loc >= 950 && loc < 1800) {
        var qx = Math.max(41, Math.min(359, RX[m]));
        rbQuiz.setAttribute('opacity', Math.min(rs(loc, 950, 1100), 1 - rs(loc, 1650, 1800)).toFixed(2));
        rbQuiz.setAttribute('transform', 'translate(' + qx + ' ' + (88 - 4 * re(rs(loc, 950, 1150))).toFixed(1) + ')');
        rbQuizBox.setAttribute('stroke', RACC[m]);
        for (var k = 0; k < 5; k++) rbDots[k].setAttribute('fill', loc < 1050 + k * 85 ? '#2A3658' : SCORE[m] === 4 && k === 2 ? '#FF6B6B' : '#3DD68C');
        rbRes.textContent = loc >= 1480 ? 'PASSED ' + SCORE[m] + '/5' : '';
      } else rbQuiz.setAttribute('opacity', 0);

      var cnt = done + '/5 DONE';
      if (cnt !== lastRbCount) { rbCount.textContent = cnt; lastRbCount = cnt; }
      var cap = grad ? 'GRADUATED · BAYES → TRANSFORMERS'
              : f < R0 || loc < 800 ? 'WALK INTO PORTAL 0' + (m + 1) + ' · ' + RNAMES[m]
              : m === 4 ? 'PASS THE QUIZ TO FINISH THE JOURNEY' : 'PASS THE QUIZ TO UNLOCK THE NEXT PORTAL';
      if (cap !== lastRbCap) { rbCap.textContent = cap; lastRbCap = cap; }
      rbFade.setAttribute('opacity', (f < 300 ? 1 - f / 300 : f > 12000 ? rs(f, 12000, RLOOP) : 0).toFixed(2));
    };
  }

  if (!drawRb) return;
  var start = performance.now(), last = 0;
  function frame(now) {
    if (now - last > 33) { last = now; drawRb(Math.max(0, now - start)); }
    requestAnimationFrame(frame);
  }
  if (reduce) drawRb(5800); else requestAnimationFrame(frame);
})();
